export function findIcon(query: string): IconEntry[] {
  const q = query.trim().toLowerCase();
  if (!q) return ICON_CATALOG.slice(0, 240);
  return ICON_CATALOG.filter((it) => it.en.toLowerCase().includes(q) || it.zh.includes(query.trim())).slice(0, 240);
}
